/// ## `model`
/// a [`ZoomModel`][crate::ZoomModel]
/// ## `icon_size`
/// use 0 for a button with text labels
///
/// # Returns
///
/// a newly created GtkButton
///
/// Since GIMP 2.4
#[doc(alias = "gimp_zoom_button_new")]
pub fn zoom_button_new(
    model: &ZoomModel,
    zoom_type: ZoomType,
    icon_size: gtk::IconSize,
) -> Option<gtk::Widget> {
    unsafe {
        from_glib_full(ffi::gimp_zoom_button_new(
            model.to_glib_none().0,
            zoom_type.into_glib(),
            icon_size.into_glib(),
        ))
    }
}
